17	package org.springframework.boot.env;
18	
19	import java.io.Closeable;
20	import java.io.IOException;
21	import java.io.InputStreamReader;
22	import java.io.LineNumberReader;
23	import java.nio.charset.Charset;
24	import java.nio.charset.StandardCharsets;
25	import java.util.ArrayList;
26	import java.util.LinkedHashMap;
27	import java.util.List;
28	import java.util.Map;
29	import java.util.function.BooleanSupplier;
30	
31	import org.jspecify.annotations.Nullable;
32	
33	import org.springframework.boot.origin.Origin;
34	import org.springframework.boot.origin.OriginTrackedValue;
