40	/**
41	 * Class to load {@code .properties} files into a map of {@code String} -&gt;
42	 * {@link OriginTrackedValue}. Also supports expansion of {@code name[]=a,b,c} list style
43	 * values.
44	 *
45	 * @author Madhura Bhave
46	 * @author Phillip Webb
47	 * @author Thiago Hirata
48	 * @author Guirong Hu
49	 * @author Moritz Halbritter
50	 */
51	class OriginTrackedPropertiesLoader {
52	
53		private final Resource resource;
54	
55		/**
56		 * Create a new {@link OriginTrackedPropertiesLoader} instance.
57		 * @param resource the resource of the {@code .properties} data
58		 */
59		OriginTrackedPropertiesLoader(Resource resource) {
60			Assert.notNull(resource, "'resource' must not be null");
61			this.resource = resource;
62		}
63	
64		/**
65		 * Load {@code .properties} data and return a list of documents.
66		 * @param encoding the resource encoding. Uses ISO-8859-1 if {@code null}
67		 * @return the loaded properties
68		 * @throws IOException on read error
69		 */
70		List<Document> load(@Nullable Charset encoding) throws IOException {
71			return load(encoding, true);
72		}
73	
74		/**
75		 * Load {@code .properties} data and return a map of {@code String} ->
76		 * {@link OriginTrackedValue}.
77		 * @param encoding the resource encoding. Uses ISO-8859-1 if {@code null}
78		 * @param expandLists if list {@code name[]=a,b,c} shortcuts should be expanded
79		 * @return the loaded properties
80		 * @throws IOException on read error
81		 */
82		List<Document> load(@Nullable Charset encoding, boolean expandLists) throws IOException {
83			List<Document> documents = new ArrayList<>();
84			Document document = new Document();
85			StringBuilder buffer = new StringBuilder();
86			try (CharacterReader reader = new CharacterReader(this.resource, encoding)) {
87				while (reader.read()) {
88					if (reader.isCommentPrefixCharacter()) {
89						char commentPrefixCharacter = reader.getCharacter();
90						if (isNewDocument(reader)) {
91							if (!document.isEmpty()) {
92								documents.add(document);
93							}
94							document = new Document();
95						}
96						else {
97							if (document.isEmpty() && !documents.isEmpty()) {
98								document = documents.remove(documents.size() - 1);
99							}
100							reader.setLastLineCommentPrefixCharacter(commentPrefixCharacter);
101							reader.skipComment();
102						}
103					}
104					else {
105						reader.setLastLineCommentPrefixCharacter(-1);
106						loadKeyAndValue(expandLists, document, reader, buffer);
107					}
108				}
109	
110			}
111			if (!document.isEmpty() && !documents.contains(document)) {
112				documents.add(document);
113			}
114			return documents;
115		}
116	
117		private void loadKeyAndValue(boolean expandLists, Document document, CharacterReader reader, StringBuilder buffer)
118				throws IOException {
119			String key = loadKey(buffer, reader).trim();
120			if (expandLists && key.endsWith("[]")) {
121				key = key.substring(0, key.length() - 2);
122				int index = 0;
123				do {
124					OriginTrackedValue value = loadValue(buffer, reader, true);
125					document.put(key + "[" + (index++) + "]", value);
126					if (!reader.isEndOfLine()) {
127						reader.read();
128					}
129				}
130				while (!reader.isEndOfLine());
131			}
132			else {
133				OriginTrackedValue value = loadValue(buffer, reader, false);
134				document.put(key, value);
135			}
136		}
137	
138		private String loadKey(StringBuilder buffer, CharacterReader reader) throws IOException {
139			buffer.setLength(0);
140			boolean previousWhitespace = false;
141			while (!reader.isEndOfLine()) {
142				if (reader.isPropertyDelimiter()) {
143					reader.read();
144					return buffer.toString();
145				}
146				if (!reader.isWhiteSpace() && previousWhitespace) {
147					return buffer.toString();
148				}
149				previousWhitespace = reader.isWhiteSpace();
150				buffer.append(reader.getCharacter());
151				reader.read();
152			}
153			return buffer.toString();
154		}
155	
156		private OriginTrackedValue loadValue(StringBuilder buffer, CharacterReader reader, boolean splitLists)
157				throws IOException {
158			buffer.setLength(0);
159			while (reader.isWhiteSpace() && !reader.isEndOfLine()) {
160				reader.read();
161			}
162			Location location = reader.getLocation();
163			while (!reader.isEndOfLine() && !(splitLists && reader.isListDelimiter())) {
164				buffer.append(reader.getCharacter());
165				reader.read();
166			}
167			Origin origin = new TextResourceOrigin(this.resource, location);
168			return OriginTrackedValue.of(buffer.toString(), origin);
169		}
170	
171		private boolean isNewDocument(CharacterReader reader) throws IOException {
172			if (reader.isSameLastLineCommentPrefix()) {
173				return false;
174			}
175			boolean result = reader.getLocation().getColumn() == 0;
176			result = result && readAndExpect(reader, reader::isHyphenCharacter);
177			result = result && readAndExpect(reader, reader::isHyphenCharacter);
178			result = result && readAndExpect(reader, reader::isHyphenCharacter);
179			if (!reader.isEndOfLine()) {
180				reader.read();
181				reader.skipWhitespace();
182			}
183			return result && reader.isEndOfLine();
184		}
185	
186		private boolean readAndExpect(CharacterReader reader, BooleanSupplier check) throws IOException {
187			reader.read();
188			return check.getAsBoolean();
189		}
190	
191		/**
192		 * Reads characters from the source resource, taking care of skipping comments,
193		 * handling multi-line values and tracking {@code '\'} escapes.
194		 */
195		private static class CharacterReader implements Closeable {
196	
197			private static final String[] ESCAPES = { "trnf", "\t\r\n\f" };
198	
199			private final LineNumberReader reader;
200	
201			private int columnNumber = -1;
202	
203			private boolean escaped;
204	
205			private int character;
206	
207			private int lastLineCommentPrefixCharacter;
208	
209			CharacterReader(Resource resource, @Nullable Charset encoding) throws IOException {
210				this.reader = new LineNumberReader(new InputStreamReader(resource.getInputStream(),
211						(encoding != null) ? encoding : StandardCharsets.ISO_8859_1));
212			}
213	
214			@Override
215			public void close() throws IOException {
216				this.reader.close();
217			}
218	
219			boolean read() throws IOException {
220				this.escaped = false;
221				this.character = this.reader.read();
222				this.columnNumber++;
223				if (this.columnNumber == 0) {
224					skipWhitespace();
225				}
226				if (this.character == '\\') {
227					this.escaped = true;
228					readEscaped();
229				}
230				else if (this.character == '\n') {
231					this.columnNumber = -1;
232				}
233				return !isEndOfFile();
234			}
235	
236			private void skipWhitespace() throws IOException {
237				while (isWhiteSpace()) {
238					this.character = this.reader.read();
239					this.columnNumber++;
240				}
241			}
242	
243			private void setLastLineCommentPrefixCharacter(int lastLineCommentPrefixCharacter) {
244				this.lastLineCommentPrefixCharacter = lastLineCommentPrefixCharacter;
245			}
246	
247			private void skipComment() throws IOException {
248				while (this.character != '\n' && this.character != -1) {
249					this.character = this.reader.read();
250				}
251				this.columnNumber = -1;
252			}
253	
254			private void readEscaped() throws IOException {
255				this.character = this.reader.read();
256				int escapeIndex = ESCAPES[0].indexOf(this.character);
257				if (escapeIndex != -1) {
258					this.character = ESCAPES[1].charAt(escapeIndex);
259				}
260				else if (this.character == '\n') {
261					this.columnNumber = -1;
262					read();
263				}
264				else if (this.character == 'u') {
265					readUnicode();
266				}
267			}
268	
269			private void readUnicode() throws IOException {
270				this.character = 0;
271				for (int i = 0; i < 4; i++) {
272					int digit = this.reader.read();
273					if (digit >= '0' && digit <= '9') {
274						this.character = (this.character << 4) + digit - '0';
275					}
276					else if (digit >= 'a' && digit <= 'f') {
277						this.character = (this.character << 4) + digit - 'a' + 10;
278					}
279					else if (digit >= 'A' && digit <= 'F') {
280						this.character = (this.character << 4) + digit - 'A' + 10;
281					}
282					else {
283						throw new IllegalStateException("Malformed \\uxxxx encoding.");
284					}
285				}
286			}
287	
288			boolean isWhiteSpace() {
289				return !this.escaped && (this.character == ' ' || this.character == '\t' || this.character == '\f');
290			}
291	
292			boolean isEndOfFile() {
293				return this.character == -1;
294			}
295	
296			boolean isEndOfLine() {
297				return this.character == -1 || (!this.escaped && this.character == '\n');
298			}
299	
300			boolean isListDelimiter() {
301				return !this.escaped && this.character == ',';
302			}
303	
304			boolean isPropertyDelimiter() {
305				return !this.escaped && (this.character == '=' || this.character == ':');
306			}
307	
308			char getCharacter() {
309				return (char) this.character;
310			}
311	
312			Location getLocation() {
313				return new Location(this.reader.getLineNumber(), this.columnNumber);
314			}
315	
316			boolean isSameLastLineCommentPrefix() {
317				return this.lastLineCommentPrefixCharacter == this.character;
318			}
319	
320			boolean isCommentPrefixCharacter() {
321				return this.character == '#' || this.character == '!';
322			}
323	
324			boolean isHyphenCharacter() {
325				return this.character == '-';
326			}
327	
328		}
329	
330		/**
331		 * A single document within the properties file.
332		 */
333		static class Document {
334	
335			private final Map<String, OriginTrackedValue> values = new LinkedHashMap<>();
336	
337			void put(String key, OriginTrackedValue value) {
338				if (!key.isEmpty()) {
339					this.values.put(key, value);
340				}
341			}
342	
343			boolean isEmpty() {
344				return this.values.isEmpty();
345			}
346	
347			Map<String, OriginTrackedValue> asMap() {
348				return this.values;
349			}
350	
351		}
352	
353	}
