49	/**
50	 * Class to load {@code .yml} files into a map of {@code String} to
51	 * {@link OriginTrackedValue}.
52	 *
53	 * @author Madhura Bhave
54	 * @author Phillip Webb
55	 */
56	class OriginTrackedYamlLoader extends YamlProcessor {
57	
58		private final Resource resource;
59	
60		OriginTrackedYamlLoader(Resource resource) {
61			this.resource = resource;
62			setResources(resource);
63		}
64	
65		@Override
66		protected Yaml createYaml() {
67			LoaderOptions loaderOptions = new LoaderOptions();
68			loaderOptions.setAllowDuplicateKeys(false);
69			loaderOptions.setMaxAliasesForCollections(Integer.MAX_VALUE);
70			loaderOptions.setAllowRecursiveKeys(true);
71			loaderOptions.setCodePointLimit(Integer.MAX_VALUE);
72			return createYaml(loaderOptions);
73		}
74	
75		private Yaml createYaml(LoaderOptions loaderOptions) {
76			BaseConstructor constructor = new OriginTrackingConstructor(loaderOptions);
77			DumperOptions dumperOptions = new DumperOptions();
78			Representer representer = new Representer(dumperOptions);
79			NoTimestampResolver resolver = new NoTimestampResolver();
80			return new Yaml(constructor, representer, dumperOptions, loaderOptions, resolver);
81		}
82	
83		List<Map<String, Object>> load() {
84			List<Map<String, Object>> result = new ArrayList<>();
85			process((properties, map) -> result.add(getFlattenedMap(map, true, "")));
86			return result;
87		}
88	
89		/**
90		 * {@link Constructor} that tracks property origins.
91		 */
92		private class OriginTrackingConstructor extends SafeConstructor {
93	
94			OriginTrackingConstructor(LoaderOptions loadingConfig) {
95				super(loadingConfig);
96			}
97	
98			@Override
99			public @Nullable Object getData() throws NoSuchElementException {
100				Object data = super.getData();
101				if (data instanceof CharSequence charSequence && charSequence.isEmpty()) {
102					return null;
103				}
104				return data;
105			}
106	
107			@Override
108			protected Object constructObject(Node node) {
109				if (node instanceof SequenceNode sequenceNode && sequenceNode.getValue().isEmpty()) {
110					return constructTrackedObject(node, "");
111				}
112				if (node instanceof ScalarNode) {
113					if (!(node instanceof KeyScalarNode)) {
114						return constructTrackedObject(node, super.constructObject(node));
115					}
116				}
117				if (node instanceof MappingNode mappingNode) {
118					replaceMappingNodeKeys(mappingNode);
119				}
120				return super.constructObject(node);
121			}
122	
123			private void replaceMappingNodeKeys(MappingNode node) {
124				List<NodeTuple> value = node.getValue();
125				List<NodeTuple> newValue = new ArrayList<>(value.size());
126				for (NodeTuple tuple : value) {
127					newValue.add(KeyScalarNode.get(tuple));
128				}
129				node.setValue(newValue);
130			}
131	
132			private Object constructTrackedObject(Node node, Object value) {
133				Origin origin = getOrigin(node);
134				return OriginTrackedValue.of(getValue(value), origin);
135			}
136	
137			private Object getValue(@Nullable Object value) {
138				return (value != null) ? value : "";
139			}
140	
141			private Origin getOrigin(Node node) {
142				Mark mark = node.getStartMark();
143				Location location = new Location(mark.getLine(), mark.getColumn());
144				return new TextResourceOrigin(OriginTrackedYamlLoader.this.resource, location);
145			}
146	
147		}
148	
149		/**
150		 * {@link ScalarNode} that replaces the key node in a {@link NodeTuple}.
151		 */
152		private static class KeyScalarNode extends ScalarNode {
153	
154			KeyScalarNode(ScalarNode node) {
155				super(node.getTag(), node.getValue(), node.getStartMark(), node.getEndMark(), node.getScalarStyle());
156			}
157	
158			static NodeTuple get(NodeTuple nodeTuple) {
159				Node keyNode = nodeTuple.getKeyNode();
160				Node valueNode = nodeTuple.getValueNode();
161				return new NodeTuple(KeyScalarNode.get(keyNode), valueNode);
162			}
163	
164			private static Node get(Node node) {
165				if (node instanceof ScalarNode scalarNode) {
166					return new KeyScalarNode(scalarNode);
167				}
168				return node;
169			}
170	
171		}
172	
173		/**
174		 * {@link Resolver} that limits {@link Tag#TIMESTAMP} tags.
175		 */
176		private static final class NoTimestampResolver extends Resolver {
177	
178			@Override
179			public void addImplicitResolver(Tag tag, Pattern regexp, String first, int limit) {
180				if (tag == Tag.TIMESTAMP) {
181					return;
182				}
183				super.addImplicitResolver(tag, regexp, first, limit);
184			}
185	
186		}
187	
188	}
