55	/**
56	 * {@link PropertySource} backed by a directory tree that contains files for each value.
57	 * The {@link PropertySource} will recursively scan a given source directory and expose a
58	 * property for each file found. The property name will be the filename, and the property
59	 * value will be the contents of the file.
60	 * <p>
61	 * Directories are only scanned when the source is first created. The directory is not
62	 * monitored for updates, so files should not be added or removed. However, the contents
63	 * of a file can be updated as long as the property source was created with a
64	 * {@link Option#ALWAYS_READ} option. Nested directories are included in the source, but
65	 * with a {@code '.'} rather than {@code '/'} used as the path separator.
66	 * <p>
67	 * Property values are returned as {@link Value} instances which allows them to be treated
68	 * either as an {@link InputStreamSource} or as a {@link CharSequence}. In addition, if
69	 * used with an {@link Environment} configured with an
70	 * {@link ApplicationConversionService}, property values can be converted to a
71	 * {@code String} or {@code byte[]}.
72	 * <p>
73	 * This property source is typically used to read Kubernetes {@code configMap} volume
74	 * mounts.
75	 *
76	 * @author Phillip Webb
77	 * @since 2.4.0
78	 */
79	public class ConfigTreePropertySource extends EnumerablePropertySource<Path>
80			implements PropertySourceInfo, OriginLookup<String> {
81	
82		private static final int MAX_DEPTH = 100;
83	
84		private final Map<String, PropertyFile> propertyFiles;
85	
86		private final String[] names;
87	
88		private final Set<Option> options;
89	
90		/**
91		 * Create a new {@link ConfigTreePropertySource} instance.
92		 * @param name the name of the property source
93		 * @param sourceDirectory the underlying source directory
94		 */
95		public ConfigTreePropertySource(String name, Path sourceDirectory) {
96			this(name, sourceDirectory, EnumSet.noneOf(Option.class));
97		}
98	
99		/**
100		 * Create a new {@link ConfigTreePropertySource} instance.
101		 * @param name the name of the property source
102		 * @param sourceDirectory the underlying source directory
103		 * @param options the property source options
104		 */
105		public ConfigTreePropertySource(String name, Path sourceDirectory, Option... options) {
106			this(name, sourceDirectory, EnumSet.copyOf(Arrays.asList(options)));
107		}
108	
109		private ConfigTreePropertySource(String name, Path sourceDirectory, Set<Option> options) {
110			super(name, sourceDirectory);
111			Assert.isTrue(Files.exists(sourceDirectory),
112					() -> "'sourceDirectory' [%s] must exist".formatted(sourceDirectory));
113			Assert.isTrue(Files.isDirectory(sourceDirectory),
114					() -> "'sourceDirectory' [%s] must be a directory".formatted(sourceDirectory));
115			this.propertyFiles = PropertyFile.findAll(sourceDirectory, options);
116			this.options = options;
117			this.names = StringUtils.toStringArray(this.propertyFiles.keySet());
118		}
119	
120		@Override
121		public String[] getPropertyNames() {
122			return this.names.clone();
123		}
124	
125		@Override
126		public @Nullable Value getProperty(String name) {
127			PropertyFile propertyFile = this.propertyFiles.get(name);
128			return (propertyFile != null) ? propertyFile.getContent() : null;
129		}
130	
131		@Override
132		public @Nullable Origin getOrigin(String name) {
133			PropertyFile propertyFile = this.propertyFiles.get(name);
134			return (propertyFile != null) ? propertyFile.getOrigin() : null;
135		}
136	
137		@Override
138		public boolean isImmutable() {
139			return !this.options.contains(Option.ALWAYS_READ);
140		}
141	
142		/**
143		 * Property source options.
144		 */
145		public enum Option {
146	
147			/**
148			 * Always read the value of the file when accessing the property value. When this
149			 * option is not set the property source will cache the value when it's first
150			 * read.
151			 */
152			ALWAYS_READ,
153	
154			/**
155			 * Convert file and directory names to lowercase.
156			 */
157			USE_LOWERCASE_NAMES,
158	
159			/**
160			 * Automatically attempt trim trailing new-line characters.
161			 */
162			AUTO_TRIM_TRAILING_NEW_LINE
163	
164		}
165	
166		/**
167		 * A value returned from the property source which exposes the contents of the
168		 * property file. Values can either be treated as {@link CharSequence} or as an
169		 * {@link InputStreamSource}.
170		 */
171		public interface Value extends CharSequence, InputStreamSource {
172	
173		}
174	
175		/**
176		 * A single property file that was found when the source was created.
177		 */
178		private static final class PropertyFile {
179	
180			private static final Location START_OF_FILE = new Location(0, 0);
181	
182			private final Path path;
183	
184			private final FileSystemResource resource;
185	
186			private final Origin origin;
187	
188			private final @Nullable PropertyFileContent cachedContent;
189	
190			private final boolean autoTrimTrailingNewLine;
191	
192			private PropertyFile(Path path, Set<Option> options) {
193				this.path = path;
194				this.resource = new FileSystemResource(path);
195				this.origin = new TextResourceOrigin(this.resource, START_OF_FILE);
196				this.autoTrimTrailingNewLine = options.contains(Option.AUTO_TRIM_TRAILING_NEW_LINE);
197				this.cachedContent = options.contains(Option.ALWAYS_READ) ? null
198						: new PropertyFileContent(path, this.resource, this.origin, true, this.autoTrimTrailingNewLine);
199			}
200	
201			PropertyFileContent getContent() {
202				if (this.cachedContent != null) {
203					return this.cachedContent;
204				}
205				return new PropertyFileContent(this.path, this.resource, this.origin, false, this.autoTrimTrailingNewLine);
206			}
207	
208			Origin getOrigin() {
209				return this.origin;
210			}
211	
212			static Map<String, PropertyFile> findAll(Path sourceDirectory, Set<Option> options) {
213				try {
214					Map<String, PropertyFile> propertyFiles = new TreeMap<>();
215					try (Stream<Path> pathStream = Files.find(sourceDirectory, MAX_DEPTH, PropertyFile::isPropertyFile,
216							FileVisitOption.FOLLOW_LINKS)) {
217						pathStream.forEach((path) -> {
218							String name = getName(sourceDirectory.relativize(path));
219							if (StringUtils.hasText(name)) {
220								if (options.contains(Option.USE_LOWERCASE_NAMES)) {
221									name = name.toLowerCase(Locale.getDefault());
222								}
223								propertyFiles.put(name, new PropertyFile(path, options));
224							}
225						});
226					}
227					return Collections.unmodifiableMap(propertyFiles);
228				}
229				catch (IOException ex) {
230					throw new IllegalStateException("Unable to find files in '" + sourceDirectory + "'", ex);
231				}
232			}
233	
234			private static boolean isPropertyFile(Path path, BasicFileAttributes attributes) {
235				return !hasHiddenPathElement(path) && (attributes.isRegularFile() || attributes.isSymbolicLink());
236			}
237	
238			private static boolean hasHiddenPathElement(Path path) {
239				for (Path element : path) {
240					if (element.toString().startsWith("..")) {
241						return true;
242					}
243				}
244				return false;
245			}
246	
247			private static String getName(Path relativePath) {
248				int nameCount = relativePath.getNameCount();
249				if (nameCount == 1) {
250					return relativePath.toString();
251				}
252				StringBuilder name = new StringBuilder();
253				for (int i = 0; i < nameCount; i++) {
254					name.append((i != 0) ? "." : "");
255					name.append(relativePath.getName(i));
256				}
257				return name.toString();
258			}
259	
260		}
261	
262		/**
263		 * The contents of a found property file.
264		 */
265		private static final class PropertyFileContent implements Value, OriginProvider {
266	
267			private final Path path;
268	
269			private final Lock resourceLock = new ReentrantLock();
270	
271			private final Resource resource;
272	
273			private final Origin origin;
274	
275			private final boolean cacheContent;
276	
277			private final boolean autoTrimTrailingNewLine;
278	
279			private volatile byte @Nullable [] content;
280	
281			private PropertyFileContent(Path path, Resource resource, Origin origin, boolean cacheContent,
282					boolean autoTrimTrailingNewLine) {
283				this.path = path;
284				this.resource = resource;
285				this.origin = origin;
286				this.cacheContent = cacheContent;
287				this.autoTrimTrailingNewLine = autoTrimTrailingNewLine;
288			}
289	
290			@Override
291			public Origin getOrigin() {
292				return this.origin;
293			}
294	
295			@Override
296			public int length() {
297				return toString().length();
298			}
299	
300			@Override
301			public char charAt(int index) {
302				return toString().charAt(index);
303			}
304	
305			@Override
306			public CharSequence subSequence(int start, int end) {
307				return toString().subSequence(start, end);
308			}
309	
310			@Override
311			public String toString() {
312				String string = new String(getBytes());
313				if (this.autoTrimTrailingNewLine) {
314					string = autoTrimTrailingNewLine(string);
315				}
316				return string;
317			}
318	
319			private String autoTrimTrailingNewLine(String string) {
320				if (!string.endsWith("\n")) {
321					return string;
322				}
323				int numberOfLines = 0;
324				for (int i = 0; i < string.length(); i++) {
325					char ch = string.charAt(i);
326					if (ch == '\n') {
327						numberOfLines++;
328					}
329				}
330				if (numberOfLines > 1) {
331					return string;
332				}
333				return (string.endsWith("\r\n")) ? string.substring(0, string.length() - 2)
334						: string.substring(0, string.length() - 1);
335			}
336	
337			@Override
338			public InputStream getInputStream() throws IOException {
339				if (!this.cacheContent) {
340					assertStillExists();
341					return this.resource.getInputStream();
342				}
343				return new ByteArrayInputStream(getBytes());
344			}
345	
346			private byte[] getBytes() {
347				try {
348					if (!this.cacheContent) {
349						assertStillExists();
350						return FileCopyUtils.copyToByteArray(this.resource.getInputStream());
351					}
352					byte[] content = this.content;
353					if (content == null) {
354						assertStillExists();
355						this.resourceLock.lock();
356						try {
357							content = this.content;
358							if (content == null) {
359								content = FileCopyUtils.copyToByteArray(this.resource.getInputStream());
360								this.content = content;
361							}
362						}
363						finally {
364							this.resourceLock.unlock();
365						}
366					}
367					return content;
368				}
369				catch (IOException ex) {
370					throw new IllegalStateException(ex);
371				}
372			}
373	
374			private void assertStillExists() {
375				Assert.state(Files.exists(this.path), () -> "The property file '" + this.path + "' no longer exists");
376			}
377	
378		}
379	
380	}
