32	/**
33	 * {@link MapPropertySource} containing default properties contributed directly to a
34	 * {@code SpringApplication}. By convention, the {@link DefaultPropertiesPropertySource}
35	 * is always the last property source in the {@link Environment}.
36	 *
37	 * @author Phillip Webb
38	 * @since 2.4.0
39	 */
40	public class DefaultPropertiesPropertySource extends MapPropertySource {
41	
42		/**
43		 * The name of the 'default properties' property source.
44		 */
45		public static final String NAME = "defaultProperties";
46	
47		/**
48		 * Create a new {@link DefaultPropertiesPropertySource} with the given {@code Map}
49		 * source.
50		 * @param source the source map
51		 */
52		public DefaultPropertiesPropertySource(Map<String, Object> source) {
53			super(NAME, source);
54		}
55	
56		/**
57		 * Return {@code true} if the given source is named 'defaultProperties'.
58		 * @param propertySource the property source to check
59		 * @return {@code true} if the name matches
60		 */
61		public static boolean hasMatchingName(@Nullable PropertySource<?> propertySource) {
62			return (propertySource != null) && propertySource.getName().equals(NAME);
63		}
64	
65		/**
66		 * Create a new {@link DefaultPropertiesPropertySource} instance if the provided
67		 * source is not empty.
68		 * @param source the {@code Map} source
69		 * @param action the action used to consume the
70		 * {@link DefaultPropertiesPropertySource}
71		 */
72		public static void ifNotEmpty(@Nullable Map<String, Object> source,
73				@Nullable Consumer<DefaultPropertiesPropertySource> action) {
74			if (!CollectionUtils.isEmpty(source) && action != null) {
75				action.accept(new DefaultPropertiesPropertySource(source));
76			}
77		}
78	
79		/**
80		 * Add a new {@link DefaultPropertiesPropertySource} or merge with an existing one.
81		 * @param source the {@code Map} source
82		 * @param sources the existing sources
83		 * @since 2.4.4
84		 */
85		public static void addOrMerge(Map<String, Object> source, MutablePropertySources sources) {
86			if (!CollectionUtils.isEmpty(source)) {
87				Map<String, Object> resultingSource = new HashMap<>();
88				DefaultPropertiesPropertySource propertySource = new DefaultPropertiesPropertySource(resultingSource);
89				if (sources.contains(NAME)) {
90					mergeIfPossible(source, sources, resultingSource);
91					sources.replace(NAME, propertySource);
92				}
93				else {
94					resultingSource.putAll(source);
95					sources.addLast(propertySource);
96				}
97			}
98		}
99	
100		@SuppressWarnings("unchecked")
101		private static void mergeIfPossible(Map<String, Object> source, MutablePropertySources sources,
102				Map<String, Object> resultingSource) {
103			PropertySource<?> existingSource = sources.get(NAME);
104			if (existingSource != null) {
105				Object underlyingSource = existingSource.getSource();
106				if (underlyingSource instanceof Map) {
107					resultingSource.putAll((Map<String, Object>) underlyingSource);
108				}
109				resultingSource.putAll(source);
110			}
111		}
112	
113		/**
114		 * Move the 'defaultProperties' property source so that it's the last source in the
115		 * given {@link ConfigurableEnvironment}.
116		 * @param environment the environment to update
117		 */
118		public static void moveToEnd(ConfigurableEnvironment environment) {
119			moveToEnd(environment.getPropertySources());
120		}
121	
122		/**
123		 * Move the 'defaultProperties' property source so that it's the last source in the
124		 * given {@link MutablePropertySources}.
125		 * @param propertySources the property sources to update
126		 */
127		public static void moveToEnd(MutablePropertySources propertySources) {
128			PropertySource<?> propertySource = propertySources.remove(NAME);
129			if (propertySource != null) {
130				propertySources.addLast(propertySource);
131			}
132		}
133	
134	}
